mapper.update:
UPDATE finance_record
amount = #{amount}, type = #{type}, category_id = #{categoryId}, account_id = #{accountId}, record_date = #{recordDate}, remark = #{remark}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT * FROM finance_record
WHERE user_id = #{userId}
  AND DATE_FORMAT(record_date, '%Y-%m') = #{month}

SELECT
DATE_FORMAT(record_date, '%d') AS name, 
SUM(amount) AS value
FROM finance_record
WHERE user_id = #{userId}
AND type = #{type}
AND DATE_FORMAT(record_date, '%Y-%m') = #{month}
GROUP BY record_date
ORDER BY record_date ASC
